def seed_invoice_sequence(apps, schema_editor):
    """Existing shops: start numbering after the last sale id, so new invoice numbers
    never look like they restart below the "#id" numbers already printed on old receipts."""
    Sale = apps.get_model("pos", "Sale")
    SystemSettings = apps.get_model("pos", "SystemSettings")
    last_sale = Sale.objects.order_by("-id").values_list("id", flat=True).first()
    if last_sale:
        settings_row, _ = SystemSettings.objects.get_or_create(pk=1)
        settings_row.next_invoice_sequence = last_sale + 1
        settings_row.save(update_fields=["next_invoice_sequence"])


